#!/usr/bin/env node
// verify-adapter-paths.mjs — deploy and verify the o-MATIC Claude Code role
// adapters (~/.claude/agents/<role>.md) from the INSTALLED packs.
// Version 2.0.0 (2026-09-28, task #983). Version 1 was task #742.
//
// CANONICAL SOURCE: o-matic-studio/studio/scripts/verify-adapter-paths.mjs.
// The copies in o-matic-firm/firm/scripts/ and o-matic-agency/agency/scripts/
// are generated by o-matic-studio/scripts/sync-pack-tooling.mjs, and its
// --check fails on drift. Edit the source, then sync.
//
// WHAT CHANGED AND WHY. Version 1 checked that each deployed adapter's
// version-pinned path ("/plugins/cache/<marketplace>/<plugin>/<version>/")
// matched the installed version. That was a re-pin, not a cure: the check
// passed on 2026-09-26 and all seven pins were stale 49 hours later, because
// nothing ran it after a pack bump (Smith #1013, RC-2). Version 2 removes the
// class instead of policing it:
//
//   1. The adapter templates no longer carry any path with a version in it.
//      Skills arrive through frontmatter `skills:` (resolved by name at load
//      time); ROLE-CORE and the runtime contract are reached relative to the
//      preloaded skill's base directory. A deployed copy is therefore a
//      BYTE-FOR-BYTE copy of the installed template — no rewrite step exists
//      to forget.
//   2. A versioned cache path in ANY deployed adapter is now a FAIL on sight,
//      whether or not it happens to match today's version. It never goes
//      back to being "fine for now".
//   3. Each pack runs this in --hook mode on SessionStart (hooks/hooks.json),
//      so a pack update is picked up the first session after it lands, on
//      every host the pack is installed on — including a second Mac that
//      never had anything deployed by hand.
//
// MODES
//   (none)      Estate-wide check over every installed pack's templates. Exit 1
//               on any FAIL. Run after a release; CI cannot (no ~/.claude there).
//   --deploy    Write every installed pack's templates into ~/.claude/agents.
//               A file that differs is moved to ~/.claude/state/adapter-backups/
//               <timestamp>/ first — never deleted. Then runs the check.
//   --hook      SessionStart mode for ONE pack (the one at $CLAUDE_PLUGIN_ROOT,
//               else this script's own pack). Installs a missing adapter,
//               updates one that is still exactly what was last deployed, and
//               REPORTS (never overwrites) one that was edited by hand or
//               predates version 2. Silent when everything is current. Always
//               exits 0: SessionStart cannot block, and a hook that crashes a
//               session start is worse than the drift it reports.
//   --home DIR  Use DIR in place of the home directory (fixtures).
//
// Backups live OUTSIDE ~/.claude/agents on purpose: Claude Code scans user
// agent directories recursively, so a backup kept beside the live files would
// load as a second agent.
import { readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync, renameSync } from "node:fs";
import { join, dirname, basename } from "node:path";
import { homedir } from "node:os";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";

const args = process.argv.slice(2);
const flag = (f) => args.includes(f);
const opt = (f) => { const i = args.indexOf(f); return i >= 0 ? args[i + 1] : undefined; };
const mode = flag("--hook") ? "hook" : flag("--deploy") ? "deploy" : "check";
const home = opt("--home") || homedir();

const agentsDir = join(home, ".claude", "agents");
const installedPath = join(home, ".claude", "plugins", "installed_plugins.json");
const statePath = join(home, ".claude", "state", "omatic-adapters.json");
const backupRoot = join(home, ".claude", "state", "adapter-backups");
const TEMPLATE_REL = join("adapters", "claude", "agents");
const PIN_RE = /\/plugins\/cache\/([^/\s`'"]+)\/([^/\s`'"]+)\/([^/\s`'"]+)\//g;

const sha = (s) => createHash("sha256").update(s).digest("hex");
const read = (p) => readFileSync(p, "utf8");
const lines = [];
let fails = 0;
const FAIL = (m) => { lines.push(`  FAIL  ${m}`); fails++; };
const OK = (m) => { if (mode !== "hook") lines.push(`  ok    ${m}`); };
const NOTE = (m) => lines.push(`  note  ${m}`);

function loadJson(p, fallback) {
  try { return JSON.parse(read(p)); } catch { return fallback; }
}

// installed_plugins.json: { plugins: { "<plugin>@<marketplace>": [{ installPath, version, gitCommitSha }] } }
function installedPacks() {
  const inst = loadJson(installedPath, null);
  if (!inst) return null;
  const packs = [];
  for (const [key, entries] of Object.entries(inst.plugins ?? {})) {
    for (const e of entries ?? []) {
      if (!e.installPath) continue;
      packs.push({ key, root: e.installPath, version: e.version, sha: e.gitCommitSha });
    }
  }
  return packs;
}

function templatesOf(packRoot) {
  const dir = join(packRoot, TEMPLATE_REL);
  if (!existsSync(dir)) return [];
  return readdirSync(dir).filter((n) => n.endsWith(".md")).map((n) => ({ name: n, path: join(dir, n) }));
}

function frontmatterSkills(txt) {
  const fm = txt.match(/^---\n([\s\S]*?)\n---/);
  if (!fm) return [];
  const m = fm[1].match(/^skills:[ \t]*(.*)$/m);
  if (!m) return [];
  if (m[1].trim().startsWith("[")) {
    return m[1].replace(/[[\]]/g, "").split(",").map((s) => s.trim().replace(/^["']|["']$/g, "")).filter(Boolean);
  }
  const after = fm[1].slice(fm[1].indexOf(m[0]) + m[0].length).split("\n");
  const out = [];
  for (const l of after) {
    const li = l.match(/^\s+-\s+(.+?)\s*$/);
    if (li) out.push(li[1].replace(/^["']|["']$/g, ""));
    else if (l.trim() !== "") break;
  }
  return out;
}

function skillResolves(name, packs) {
  const bare = name.includes(":") ? name.split(":").pop() : name;
  return packs.some((p) => existsSync(join(p.root, "skills", bare, "SKILL.md")));
}

function backup(file, stamp) {
  const dir = join(backupRoot, stamp);
  mkdirSync(dir, { recursive: true });
  const dest = join(dir, basename(file));
  renameSync(file, dest);
  return dest;
}

function recordDeploy(state, name, content, source) {
  state[name] = { sha256: sha(content), source, deployed_at: new Date().toISOString() };
}

// Checks every deployed adapter can fail on, whatever the mode.
function checkFile(name, txt, packs, template) {
  const pins = new Set([...txt.matchAll(PIN_RE)].map((m) => `${m[1]}/${m[2]}@${m[3]}`));
  for (const p of pins)
    FAIL(`${name}: carries a version-pinned cache path (${p}) — the pin class task #983 removed; redeploy from the installed template`);
  for (const s of frontmatterSkills(txt)) {
    if (skillResolves(s, packs)) OK(`${name}: frontmatter skill '${s}' resolves in an installed pack`);
    else FAIL(`${name}: frontmatter skill '${s}' is not shipped by any installed pack`);
  }
  if (template) {
    if (txt === template.content) OK(`${name}: identical to ${template.source} template`);
    else FAIL(`${name}: differs from the ${template.source} template — run with --deploy to adopt it (the old file is backed up, not deleted)`);
  }
}

function main() {
  const packs = installedPacks();
  if (!packs) {
    if (mode === "hook") process.exit(0); // nothing to say on a host with no plugin record
    FAIL(`${installedPath} not found or unreadable — cannot resolve installed packs`);
    return finish();
  }
  for (const p of packs)
    if (existsSync(join(p.root, ".orphaned_at")))
      FAIL(`${p.key}: installed_plugins.json points at ${p.root}, which carries .orphaned_at`);

  // Which templates are in scope.
  let scope;
  if (mode === "hook") {
    const own = process.env.CLAUDE_PLUGIN_ROOT || join(dirname(fileURLToPath(import.meta.url)), "..");
    const pack = packs.find((p) => p.root === own) || { key: basename(own), root: own, version: "?" };
    scope = [pack];
  } else {
    scope = packs;
  }
  const templates = new Map(); // agent file name -> { content, source }
  for (const p of scope)
    for (const t of templatesOf(p.root))
      templates.set(t.name, { content: read(t.path), source: `${p.key} ${p.version}` });

  const state = loadJson(statePath, {});
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  let stateDirty = false;
  mkdirSync(agentsDir, { recursive: true });

  for (const [name, t] of templates) {
    const file = join(agentsDir, name);
    const cur = existsSync(file) ? read(file) : null;
    if (cur === t.content) {
      if (!state[name] || state[name].sha256 !== sha(cur)) { recordDeploy(state, name, cur, t.source); stateDirty = true; }
      continue;
    }
    const untouched = cur !== null && state[name] && state[name].sha256 === sha(cur);
    if (mode === "deploy" || (mode === "hook" && (cur === null || untouched))) {
      const moved = cur !== null ? backup(file, stamp) : null;
      writeFileSync(file, t.content);
      recordDeploy(state, name, t.content, t.source);
      stateDirty = true;
      NOTE(`${name}: ${cur === null ? "installed" : "updated"} from ${t.source}${moved ? ` (previous copy kept at ${moved})` : ""}`);
    }
  }
  if (stateDirty) {
    mkdirSync(dirname(statePath), { recursive: true });
    writeFileSync(statePath, JSON.stringify(state, null, 1) + "\n");
  }

  // Verify. Hook mode checks only this pack's adapters; the other modes check
  // every file in ~/.claude/agents, including ones no pack ships (a pin in a
  // hand-written adapter is the same defect).
  const names = mode === "hook"
    ? [...templates.keys()]
    : readdirSync(agentsDir).filter((n) => n.endsWith(".md"));
  for (const name of names) {
    const file = join(agentsDir, name);
    if (!existsSync(file)) { FAIL(`${name}: shipped by ${templates.get(name).source} but not deployed`); continue; }
    checkFile(name, read(file), packs, templates.get(name));
  }
  if (mode !== "hook")
    for (const name of templates.keys())
      if (!names.includes(name)) FAIL(`${name}: shipped by ${templates.get(name).source} but not deployed`);
  return finish(names.length);
}

function finish(n = 0) {
  if (mode === "hook") {
    if (lines.length) {
      console.log(`o-MATIC role adapters (verify-adapter-paths --hook, ${fails} problem(s)):`);
      console.log(lines.join("\n"));
      if (fails) console.log("  Fix: node <this pack>/scripts/verify-adapter-paths.mjs --deploy   (backs up before replacing)");
    }
    process.exit(0);
  }
  console.log(`\n=== o-MATIC role adapters under ${agentsDir} (${mode}) ===\n`);
  if (lines.length) console.log(lines.join("\n"));
  console.log(`\n${fails ? "RESULT: FAIL" : "RESULT: PASS"} — ${n} adapter file(s) checked, ${fails} fail\n`);
  process.exit(fails ? 1 : 0);
}

main();
